/*
The following script define a method
that increments an integer by 1 
and registers it as a UDF with 
the SparkSession, which can be accessed
using the variable named "spark":
def inc(i: Integer): Integer = {
  i + 1
}
spark.udf.register ("inc", inc _)

*/

if records:
    for record in records:

        # 1. Copy optional enrichment fields from record header attributes.
        #    The Expression Evaluator resolves pipeline-level runtime
        #    parameters into these header attributes before this stage.
        #    Empty string means "skip" — the field is not written.
        enrichment_map = {
            'source_system': record.attributes.get('enrichSourceSystem', ''),
            'environment':   record.attributes.get('enrichEnvironment', ''),
            'pipeline_name': record.attributes.get('enrichPipelineName', ''),
            'schema_version': record.attributes.get('enrichSchemaVersion', ''),
        }
        for field_name, value in enrichment_map.items():
            if value:
                record.value[field_name] = value

        output.write(record)

